<script setup>
import { onBeforeUnmount } from 'vue'
const props=defineProps({language:{default:"lustro"}})
const catalogSearch=ref('')
const notificationsRead=ref(false)
const volume=ref(64)
const step=ref(1)
const pickedFile=ref('No file selected')
const formName=ref('')
const formSent=ref(false)
const failed=ref(true)
const dialogRef=ref(), sheetRef=ref(), opener=ref()
function openNative(which,event){opener.value=event.currentTarget;(which==='modal'?dialogRef:sheetRef).value.showModal()}
function restore(){opener.value?.focus()}
function selectFile(event){const f=event.target.files?.[0];pickedFile.value=f?f.name+' · '+Math.ceil(f.size/1024)+' KB':'No file selected'}

import { ref } from 'vue'
const toasts = ref([])
let nextToastId = 0
const toastTimers = new Map()
const alertOpen = ref(true)
const modalOpen = ref(false)
const tab = ref('Overview')
const search = ref('')
const choice = ref('Design')
const accordion = ref('Tokens')
const page = ref(1)
const slide = ref(0)
const drawerOpen = ref(false)
const navOpen = ref(false)
const menuSection = ref('Inicio')
function dismissToast(id) {
  toasts.value = toasts.value.filter(item => item.id !== id)
  clearTimeout(toastTimers.get(id))
  toastTimers.delete(id)
}
function showToast(message, type = 'info') {
  const id = ++nextToastId
  toasts.value.push({ id, message, type })
  toastTimers.set(id, setTimeout(() => dismissToast(id), 6000))
}

onBeforeUnmount(()=>toastTimers.forEach(clearTimeout))
</script>
